  return ok and blocked == false
end

local function BetterQoL_CmdrQuery()
  local q = { locked = false, why = "" }
  if not BetterQoL.commander_guide_hidden or type(funcLuaCommand) ~= "function" then
    q.why = "off"
    return q
  end
  local online = false
  if type(CheckExistsObserver) == "function" then
    local ok, r = pcall(CheckExistsObserver)
    online = ok and r == true
  end
  q.online = online
  local ok, coach = pcall(funcLuaCommand, BETTERQOL_CMDR_CMD_MODE)
  q.coach = ok and coach
  local ok2, observe = pcall(funcLuaCommand, BETTERQOL_CMDR_CMD_OBSERVE)
  q.observe = ok2 and observe
  local ok3, valid, game = pcall(funcLuaCommand, BETTERQOL_CMDR_CMD_GAME)
  q.valid, q.game = ok3 and valid, ok3 and game
  local ok4, has, diff = pcall(funcLuaCommand, BETTERQOL_CMDR_CMD_DIFF)
  q.has, q.diff = ok4 and has, ok4 and diff
  if online then
    q.why = "online/observer"
  elseif not ok or coach then
    q.why = "commander mode already on (or query failed)"
  elseif not ok2 or observe then
    q.why = "spectator on (or query failed)"
  elseif not ok3 or not valid or type(game) ~= "number" or game == 0 then
    q.why = "no valid game id"
  elseif not ok4 or not has or type(diff) ~= "number" then
    q.why = "no difficulty"
  elseif BetterQoL_CmdrGateOpen() then
    q.why = "gate open"
  else
    local ok5, cleared = pcall(funcLuaCommand, BETTERQOL_CMDR_CMD_CLEAR, game, diff)
    q.cleared = ok5 and cleared
    if not ok5 or cleared == nil then
      q.why = "clear query failed"
    elseif cleared == true then
      q.why = "rival beaten"
    else
      q.locked = true
      q.why = "not beaten"
    end
  end
  return q
end

-- Hides instance 1 of the guide layer (0 is the bench request, 2 the spectator) when the layer is open.
