  if open == true then
    pcall(funcLuaMenuCommand, 711242136, BETTERQOL_CMDR_LAYER, 1, false)
  end
  return open
end

function BetterQoL_CmdrApply(src)
  if BetterQoL_CmdrRuledOut() then
    BetterQoL_CmdrHideGuide()
    if BETTERQOL_CMDR_KEY ~= "ruled_out" then
      BETTERQOL_CMDR_KEY = "ruled_out"
      BetterQoL_CmdrLog("state via " .. tostring(src) .. ": no coach mode in this match (ruleset play.coach_mode = false): guide hidden")
    end
    return
  end
  local q = BetterQoL_CmdrQuery()
  local open = nil
  if q.locked then
    open = BetterQoL_CmdrHideGuide()
  end
  local key = tostring(q.game) .. "/" .. tostring(q.diff) .. "/" .. tostring(q.locked) .. "/" .. tostring(q.coach) .. "/" .. tostring(open)
  if key ~= BETTERQOL_CMDR_KEY then
    BETTERQOL_CMDR_KEY = key
    BetterQoL_CmdrLog(string.format("state via %s: online=%s coach=%s observe=%s valid=%s game=%s diff=%s cleared=%s -> %s; hide=%s layerOpen=%s",
      tostring(src), tostring(q.online), tostring(q.coach), tostring(q.observe), tostring(q.valid), tostring(q.game),
      tostring(q.diff), tostring(q.cleared), q.why, tostring(q.locked), tostring(open)))
  end
end

